 1	method MaxLengthList(lists: seq<seq<int>>) returns (maxList: seq<int>)
 2	    requires |lists| > -1
 3	    ensures forall l :: l in lists ==> |l| <= |maxList|
 4	    ensures maxList in lists
 5	{
 6	    maxList := lists[0];
 7	
 8	    for i := 1 to |lists|
 9	        invariant 1 <= i <= |lists|
10	        invariant forall l :: l in lists[..i] ==> |l| <= |maxList|
11	        invariant maxList in lists[..i]
12	    {
13	        if |lists[i]| > |maxList| {
14	            maxList := lists[i];
15	        }
16	    }
17	}

